<?php require __DIR__.'/bootstrap.php'; $id=(int)($_GET['id']??0);$q=db()->prepare('SELECT c.*,u.name owner_name,u.phone owner_phone,u.email owner_email FROM cars c JOIN users u ON u.id=c.owner_id WHERE c.id=? AND c.status="active"');$q->execute([$id]);$car=$q->fetch();if(!$car){http_response_code(404);exit('Car not found.');}$im=db()->prepare('SELECT image_path FROM car_images WHERE car_id=? ORDER BY sort_order,id');$im->execute([$id]);$images=$im->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['buyer_name']??'');$email=filter_var($_POST['buyer_email']??'',FILTER_VALIDATE_EMAIL);$phone=trim($_POST['buyer_phone']??'');$message=trim($_POST['message']??'');if(!$name||!$email||!$phone||!$message){flash('Please complete every inquiry field.');}else{db()->prepare('INSERT INTO inquiries(car_id,buyer_id,buyer_name,buyer_email,buyer_phone,message) VALUES(?,?,?,?,?,?)')->execute([$id,current_user()['id']??null,$name,$email,$phone,$message]);flash('Your inquiry was saved. The dealer can contact you directly.');redirect('car-details.php?id='.$id);}}
page_top($car['title']);$first=$images[0]['image_path']??'assets/car-placeholder.svg'; ?><div class="detail"><section><img src="<?=e($first)?>" alt="<?=e($car['title'])?>"><?php if(count($images)>1): ?><div class="thumbs"><?php foreach($images as $image): ?><img src="<?=e($image['image_path'])?>" alt="Car image"><?php endforeach ?></div><?php endif ?></section><section><h1><?=e($car['title'])?></h1><p class="price">₹<?=number_format((float)$car['price'])?></p><div class="specs"><span><b>Brand:</b> <?=e($car['brand'])?></span><span><b>Model:</b> <?=e($car['model'])?></span><span><b>Year:</b> <?=e($car['year'])?></span><span><b>Mileage:</b> <?=e($car['mileage'])?> km</span><span><b>Fuel:</b> <?=e($car['fuel_type'])?></span><span><b>Transmission:</b> <?=e($car['transmission'])?></span></div><p><?=nl2br(e($car['description']))?></p><h2>Dealer contact</h2><p><?=e($car['owner_name'])?><br><a href="tel:<?=e($car['owner_phone'])?>"><?=e($car['owner_phone'])?></a><br><a href="mailto:<?=e($car['owner_email'])?>"><?=e($car['owner_email'])?></a></p><form class="form-card" method="post"><h2>Send inquiry</h2><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Name</label><input name="buyer_name" required><label>Email</label><input name="buyer_email" type="email" required><label>Phone</label><input name="buyer_phone" required><label>Message</label><textarea name="message" required></textarea><button class="button">Send inquiry</button></form></section></div><?php page_bottom();
